package cl.bolsillo.app;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Long-press selection on the review list; discards remain in the encrypted evidence history. */
final class ReviewSelection {
 static boolean cancel(MainActivity a){if(!a.reviewSelecting)return false;a.reviewSelecting=false;a.reviewSelection.clear();a.render(false);return true;}
 static void start(MainActivity a,String id){a.reviewSelecting=true;if(!id.isEmpty())a.reviewSelection.add(id);a.render(false);}
 static LinkedHashMap<String,JSONObject> requests(MainActivity a,boolean approve)throws Exception{LinkedHashMap<String,JSONObject> result=new LinkedHashMap<>();JSONObject data=LocalData.read(a);JSONArray inbox=NativeStore.inbox(a);if(inbox!=null)for(int i=0;i<inbox.length();i++){JSONObject e=inbox.getJSONObject(i);if(!a.reviewSelection.contains(e.optString("id")))continue;if(approve)Ledger.require(AutomationScreen.batchReady(data,e),"Revisa primero «"+e.optString("merchant","Este aviso")+"»: necesita datos o comprobar un posible duplicado.");result.put(e.getString("id"),approve?Detection.transaction(a,e,true):null);}JSONArray transactions=data.getJSONArray("transactions");for(int i=0;i<transactions.length();i++){JSONObject pending=transactions.getJSONObject(i);String key="pending:"+pending.optString("id");if(pending.optString("status").equals("pending")&&a.reviewSelection.contains(key))result.put(key,approve?new JSONObject(pending.toString()).put("status","posted"):null);}Ledger.require(!result.isEmpty(),"Selecciona al menos un registro pendiente");return result;}
 static void commit(MainActivity a,boolean approve){a.attempt(()->{LinkedHashMap<String,JSONObject> wanted=requests(a,approve);a.confirm((approve?"Aprobar ":"Descartar ")+wanted.size()+" avisos",approve?"Se registrarán los avisos seleccionados con sus montos, cuentas y categorías actuales.":"Se quitarán de Revisión los avisos y registros pendientes seleccionados. No cambiarán los saldos. Se conserva su historial.",()->{synchronized(NativeStore.class){NativeStore.resolveDetections(a,requests(a,approve));}a.reviewSelecting=false;a.reviewSelection.clear();NativeSync.run(a,null);BolsilloWidget.updateAll(a);a.render(false);});});}
 static void show(MainActivity a)throws Exception{
  JSONArray inbox=NativeStore.inbox(a);Set<String> existing=new HashSet<>();if(inbox!=null)for(int i=0;i<inbox.length();i++)existing.add(inbox.getJSONObject(i).optString("id"));JSONArray pendingTransactions=a.data.getJSONArray("transactions");for(int i=0;i<pendingTransactions.length();i++)if(pendingTransactions.getJSONObject(i).optString("status").equals("pending"))existing.add("pending:"+pendingTransactions.getJSONObject(i).optString("id"));a.reviewSelection.retainAll(existing);
  LinearLayout bar=Modern.column(a);final TextView count=Modern.text(a,"",15,Glass.ink(a),true);final Button approve=Glass.button(a,"Aprobar"),discard=Glass.button(a,"Descartar");Runnable refresh=()->{count.setText(a.reviewSelection.size()+(a.reviewSelection.size()==1?" seleccionado":" seleccionados"));approve.setEnabled(!a.reviewSelection.isEmpty());discard.setEnabled(!a.reviewSelection.isEmpty());};
  if(a.reviewSelecting){LinearLayout heading=Modern.row(a);heading.addView(count,new LinearLayout.LayoutParams(0,-2,1));heading.addView(Modern.iconButton(a,"close","Salir de selección",()->cancel(a)),new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));bar.addView(heading);LinearLayout actions=Modern.row(a);actions.addView(approve,new LinearLayout.LayoutParams(0,a.dp(48),1));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(0,a.dp(48),1);dp.leftMargin=a.dp(8);actions.addView(discard,dp);Modern.add(bar,actions,8);approve.setOnClickListener(v->commit(a,true));discard.setOnClickListener(v->commit(a,false));TextView all=Modern.text(a,a.reviewSelection.size()==existing.size()?"Desmarcar todos":"Seleccionar todos",12,Glass.accent(a),true);all.setMinHeight(a.dp(44));all.setGravity(Gravity.CENTER_VERTICAL);bar.addView(all);Modern.press(all,()->{if(a.reviewSelection.containsAll(existing))a.reviewSelection.clear();else a.reviewSelection.addAll(existing);a.render(false);});Modern.add(a.body,bar,12);refresh.run();}
  else{Modern.section(a,"Por confirmar",existing.size()>1?"Seleccionar":"",()->start(a,""));a.body.getChildAt(a.body.getChildCount()-1).setTag("tutorial-review");if(!existing.isEmpty())Modern.add(a.body,Modern.text(a,"Mantén pulsado para seleccionar varios",11,Glass.subtle(a),false),0);}
  List<JSONObject> records=new ArrayList<>();if(inbox!=null)for(int i=inbox.length()-1;i>=0;i--)records.add(inbox.getJSONObject(i));for(int i=0;i<pendingTransactions.length();i++){JSONObject tx=pendingTransactions.getJSONObject(i);if(tx.optString("status").equals("pending"))records.add(new JSONObject().put("id","pending:"+tx.getString("id")).put("merchant",tx.optString("note").isEmpty()?"Movimiento pendiente":tx.optString("note")).put("reason","Registro pendiente").put("amount",tx.optLong("amount")).put("date",tx.optString("date")));}for(JSONObject e:records){String id=e.getString("id");CheckBox[] selectionCheck={null};View row=Modern.item(a,Modern.iconFor(e.optString("merchant")),e.optString("merchant"),e.optString("date",Detection.date(e.optLong("at")))+" · "+e.optString("reason"),e.optLong("amount")>0?a.money(e.optLong("amount")):"Elegir monto",Glass.AMBER,()->{if(a.reviewSelecting&&selectionCheck[0]!=null){selectionCheck[0].toggle();}else if(id.startsWith("pending:"))a.attempt(()->Forms.transactionMenu(a,Ledger.find(a.data.getJSONArray("transactions"),id.substring(8))));else AutomationScreen.reviewItem(a,e);});row.setOnLongClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);if(a.reviewSelecting&&selectionCheck[0]!=null)selectionCheck[0].toggle();else start(a,id);return true;});if(a.reviewSelecting){LinearLayout outer=Modern.row(a);CheckBox check=new CheckBox(a);selectionCheck[0]=check;Controls.style(check);check.setContentDescription("Seleccionar "+e.optString("merchant"));check.setChecked(a.reviewSelection.contains(id));check.setMinWidth(a.dp(44));outer.addView(check,new LinearLayout.LayoutParams(a.dp(44),a.dp(60)));outer.addView(row,new LinearLayout.LayoutParams(0,-2,1));check.setOnCheckedChangeListener((v,on)->{if(on)a.reviewSelection.add(id);else a.reviewSelection.remove(id);refresh.run();});Modern.add(a.body,outer,8);}else Modern.add(a.body,row,8);}
  if(existing.isEmpty())Modern.empty(a,"check","Todo al día","No hay movimientos que necesiten revisión.","",()->{});
 }
}
